WEEKLY_ROUTE = '\n# ===== MEALORA WEEKLY PLANNER V3 START =====\n@app.route("/api/weekly-plan", methods=["POST"])\ndef weekly_plan_v3():\n    """\n    Pantry-first weekly planner.\n\n    Key correction:\n    - Do NOT ask the generic recommender for 35 recipes and then try to\n      optimize them. That caused pantry_score=0 and irrelevant recipes.\n    - Score the full recipe master dataset against the CURRENT pantry first.\n    - Use pantry coverage as a strong gate/objective.\n    - Keep ML/context as ranking signals, not as permission to ignore the pantry.\n    - Build meal/side roles from pantry-compatible candidates.\n    """\n    try:\n        import ast\n        import random\n        import re as _re\n        from difflib import SequenceMatcher\n        import numpy as np\n        import pandas as pd\n\n        data = request.get_json() or {}\n        pantry = data.get("pantry") or []\n        household = data.get("household") or {}\n\n        adults = max(int(household.get("adults", 0) or 0), 0)\n        children = max(int(household.get("children", 0) or 0), 0)\n        seniors = max(int(household.get("seniors", 0) or 0), 0)\n\n        if adults + children + seniors <= 0:\n            return jsonify({\n                "success": False,\n                "error": "Add at least one household member."\n            }), 400\n\n        mode = str(data.get("mode", "automatic") or "automatic").lower()\n        diet = str(data.get("diet", "Mixed") or "Mixed")\n        cuisine = str(data.get("cuisine", "Auto") or "Auto")\n        max_time = float(data.get("max_time", 60) or 60)\n        include_snacks = bool(data.get("include_snacks", True))\n        special_day = str(data.get("special_day", "Saturday") or "None")\n\n        ctx = build_context({\n            "mode": mode,\n            "date": data.get("date"),\n            "time": data.get("time"),\n            "location_city": data.get("location_city"),\n            "location": data.get("location_city"),\n            "latitude": data.get("latitude"),\n            "longitude": data.get("longitude"),\n            "meal_type": data.get("meal_type", "Automatic"),\n            "diet": diet,\n            "cuisine": cuisine,\n            "max_time": max_time,\n        })\n\n        if diet.lower() in ("auto", "automatic"):\n            diet = ctx.get("diet", diet)\n        if cuisine.lower() in ("auto", "automatic"):\n            cuisine = ctx.get("cuisine", cuisine)\n\n        def norm_text(value):\n            s = str(value or "").lower()\n            s = s.replace("&", " and ")\n            s = s.replace("chilli", "chili")\n            s = s.replace("capsicum", "bell pepper")\n            s = s.replace("coriander leaves", "cilantro")\n            s = s.replace("coriander leaf", "cilantro")\n            s = s.replace("curd", "yogurt")\n            s = s.replace("dahi", "yogurt")\n            s = _re.sub(r"[^a-z0-9\\s]", " ", s)\n            s = _re.sub(r"\\s+", " ", s).strip()\n            return s\n\n        def token_set(value):\n            return {\n                x for x in norm_text(value).split()\n                if len(x) >= 3 and x not in {\n                    "the", "and", "with", "for", "from", "into",\n                    "cup", "cups", "tsp", "tbsp", "tablespoon",\n                    "tablespoons", "teaspoon", "teaspoons"\n                }\n            }\n\n        UNIT_RE = (\n            r"(?:kg|kgs|kilo|kilos|kilogram|kilograms|g|gram|grams|"\n            r"ml|milliliter|milliliters|litre|litres|liter|liters|"\n            r"l|piece|pieces|pcs|clove|cloves|bunch|bunches|"\n            r"slice|slices|tbsp|tsp|cup|cups|pinch|handful)"\n        )\n\n        def clean_ingredient_name(value):\n            s = str(value or "").strip()\n            if not s:\n                return ""\n\n            # Remove leading quantity/unit.\n            s = _re.sub(\n                rf"^\\s*\\d+(?:\\.\\d+)?\\s*(?:{UNIT_RE})?\\s*(?:of\\s+)?",\n                "",\n                s,\n                flags=_re.I,\n            )\n\n            # Remove common parenthetical notes.\n            s = _re.sub(r"\\([^)]*\\)", " ", s)\n\n            # Remove preparation tails that should not become ingredient names.\n            s = _re.sub(\n                r"\\b(chopped|sliced|diced|minced|grated|crushed|"\n                r"finely|roughly|freshly|to taste|as needed)\\b",\n                " ",\n                s,\n                flags=_re.I,\n            )\n\n            s = _re.sub(r"\\s+", " ", s).strip(" ,.-")\n            return s\n\n        def parse_ingredients(value):\n            if isinstance(value, list):\n                return [\n                    clean_ingredient_name(x)\n                    for x in value\n                    if clean_ingredient_name(x)\n                ]\n\n            if value is None:\n                return []\n\n            s = str(value).strip()\n            if not s or s.lower() in ("nan", "none", "null"):\n                return []\n\n            # Python/JSON list stored as text.\n            if s.startswith("[") and s.endswith("]"):\n                for parser in (json.loads, ast.literal_eval):\n                    try:\n                        parsed = parser(s)\n                        if isinstance(parsed, list):\n                            return [\n                                clean_ingredient_name(x)\n                                for x in parsed\n                                if clean_ingredient_name(x)\n                            ]\n                    except Exception:\n                        pass\n\n            # Newline / semicolon / pipe separated datasets.\n            parts = re.split(r"\\n|;|\\|", s)\n            if len(parts) == 1:\n                # Some datasets use comma-separated ingredient lists.\n                parts = [x.strip() for x in s.split(",")]\n\n            return [\n                clean_ingredient_name(x)\n                for x in parts\n                if clean_ingredient_name(x)\n            ]\n\n        def first_col(df, candidates):\n            lower = {str(c).lower(): c for c in df.columns}\n            for c in candidates:\n                if str(c).lower() in lower:\n                    return lower[str(c).lower()]\n            return None\n\n        # ------------------------------------------------------------\n        # Current pantry -> normalized pantry names.\n        # ------------------------------------------------------------\n        pantry_names = []\n        pantry_expiry_names = []\n\n        today = now_india().date()\n\n        for item in pantry:\n            name = (\n                item.get("normalized_name")\n                or item.get("ingredient_name")\n                or item.get("name")\n            )\n            if not name:\n                continue\n\n            cleaned = clean_ingredient_name(name)\n            if cleaned:\n                pantry_names.append(cleaned)\n\n            expiry = item.get("expiry_date")\n            if expiry:\n                try:\n                    days = (\n                        datetime.strptime(\n                            str(expiry)[:10], "%Y-%m-%d"\n                        ).date() - today\n                    ).days\n                    if days <= 7:\n                        pantry_expiry_names.append(cleaned)\n                except Exception:\n                    pass\n\n        # De-duplicate pantry aliases.\n        pantry_names = list(dict.fromkeys(pantry_names))\n        pantry_expiry_names = list(dict.fromkeys(pantry_expiry_names))\n\n        if not pantry_names:\n            return jsonify({\n                "success": False,\n                "error": "Your pantry is empty. Add ingredients before generating the weekly plan."\n            }), 400\n\n        # Staple ingredients should help a recipe, but should not make a\n        # recipe look pantry-complete by themselves.\n        STAPLES = {\n            "salt", "sugar", "water", "oil", "cooking oil",\n            "sunflower oil", "groundnut oil", "coconut oil",\n            "mustard oil", "sesame oil", "olive oil", "ghee",\n            "butter", "black pepper", "turmeric", "turmeric powder",\n            "red chili", "red chili powder", "coriander powder",\n            "cumin powder", "garam masala", "hing", "asafoetida",\n            "ginger garlic paste"\n        }\n\n        def ingredient_match(recipe_ing, pantry_name):\n            a = norm_text(recipe_ing)\n            b = norm_text(pantry_name)\n\n            if not a or not b:\n                return False\n\n            if a == b or a in b or b in a:\n                return True\n\n            at = token_set(a)\n            bt = token_set(b)\n\n            if not at or not bt:\n                return False\n\n            # Strong token overlap.\n            overlap = len(at & bt) / max(len(at), len(bt))\n            if overlap >= 0.70:\n                return True\n\n            # Singular/plural and common-word similarity.\n            for x in at:\n                for y in bt:\n                    if len(x) >= 5 and len(y) >= 5:\n                        if SequenceMatcher(None, x, y).ratio() >= 0.88:\n                            return True\n\n            return False\n\n        def score_recipe(recipe_ingredients):\n            ingredients = [\n                x for x in recipe_ingredients\n                if norm_text(x)\n            ]\n\n            if not ingredients:\n                return {\n                    "pantry": 0.0,\n                    "core_pantry": 0.0,\n                    "expiry": 0.0,\n                    "matched": [],\n                    "missing": [],\n                    "missing_core": [],\n                }\n\n            matched = []\n            missing = []\n            missing_core = []\n            matched_expiry = []\n\n            core_ingredients = []\n\n            for ing in ingredients:\n                is_staple = norm_text(ing) in {\n                    norm_text(x) for x in STAPLES\n                }\n\n                if not is_staple:\n                    core_ingredients.append(ing)\n\n                match = next(\n                    (\n                        p for p in pantry_names\n                        if ingredient_match(ing, p)\n                    ),\n                    None,\n                )\n\n                if match:\n                    matched.append(match)\n\n                    if any(\n                        ingredient_match(ing, e)\n                        for e in pantry_expiry_names\n                    ):\n                        matched_expiry.append(match)\n                else:\n                    missing.append(ing)\n                    if not is_staple:\n                        missing_core.append(ing)\n\n            all_coverage = len(matched) / max(len(ingredients), 1)\n\n            if core_ingredients:\n                core_matched = len(core_ingredients) - len(missing_core)\n                core_coverage = core_matched / len(core_ingredients)\n            else:\n                core_coverage = all_coverage\n\n            expiry_coverage = (\n                len(set(matched_expiry))\n                / max(len(set(pantry_expiry_names)), 1)\n                if pantry_expiry_names\n                else 0.0\n            )\n\n            # Pantry coverage is about recipe requirements, NOT\n            # recipe-match-count / 139 pantry rows.\n            pantry_score = (\n                0.75 * core_coverage +\n                0.25 * all_coverage\n            )\n\n            return {\n                "pantry": float(np.clip(pantry_score, 0, 1)),\n                "core_pantry": float(np.clip(core_coverage, 0, 1)),\n                "expiry": float(np.clip(expiry_coverage, 0, 1)),\n                "matched": list(dict.fromkeys(matched)),\n                "missing": missing,\n                "missing_core": missing_core,\n            }\n\n        # ------------------------------------------------------------\n        # Load the COMPLETE recipe master dataset.\n        # ------------------------------------------------------------\n        df = pd.read_csv(RECIPE_DATASET)\n\n        if df.empty:\n            raise RuntimeError("The recipe master dataset is empty.")\n\n        name_col = first_col(\n            df,\n            ["recipe_name", "name", "title", "recipe", "dish_name"]\n        )\n        id_col = first_col(\n            df,\n            ["recipe_id", "id", "ID", "recipeid"]\n        )\n        ingredient_col = first_col(\n            df,\n            [\n                "ingredients", "ingredient_names",\n                "cleaned_ingredients", "Cleaned-Ingredients",\n                "TranslatedIngredients", "ingredient_list",\n                "Ingredients"\n            ]\n        )\n        meal_col = first_col(\n            df,\n            ["meal_type", "meal", "mealtype", "meal_type_name"]\n        )\n        cuisine_col = first_col(\n            df,\n            ["cuisine", "cuisine_type"]\n        )\n        diet_col = first_col(\n            df,\n            ["diet", "diet_type", "diet_category"]\n        )\n        time_col = first_col(\n            df,\n            [\n                "cooking_time_minutes", "cooking_time",\n                "cook_time", "prep_time_minutes",\n                "total_time_minutes", "total_time"\n            ]\n        )\n\n        if name_col is None or ingredient_col is None:\n            raise RuntimeError(\n                "Mealora could not identify recipe_name/ingredients columns "\n                f"in {RECIPE_DATASET}."\n            )\n\n        # Deduplicate recipes.\n        df = df.copy()\n        df["_mealora_recipe_name"] = (\n            df[name_col].fillna("Mealora Recipe").astype(str).str.strip()\n        )\n        df["_mealora_ingredients"] = df[ingredient_col].apply(parse_ingredients)\n\n        if id_col:\n            df["_mealora_recipe_id"] = df[id_col].astype(str)\n        else:\n            df["_mealora_recipe_id"] = [\n                str(i) for i in range(len(df))\n            ]\n\n        # Remove unusable rows.\n        df = df[\n            (df["_mealora_recipe_name"] != "") &\n            (df["_mealora_ingredients"].map(len) > 0)\n        ].copy()\n\n        # ------------------------------------------------------------\n        # Context / ML columns if they already exist in the master.\n        # Otherwise use conservative neutral defaults.\n        # ------------------------------------------------------------\n        def row_score(row, candidates, default=0.5):\n            for c in candidates:\n                if c in row.index:\n                    try:\n                        value = float(row[c])\n                        if np.isfinite(value):\n                            return float(np.clip(value, 0, 1))\n                    except Exception:\n                        pass\n            return default\n\n        def classify_meal(row, recipe_name, ingredients):\n            raw = str(row.get(meal_col, "") if meal_col else "").lower()\n            text = f"{recipe_name} {\' \'.join(ingredients)}".lower()\n\n            if any(x in raw for x in ["breakfast", "morning"]):\n                return "Breakfast"\n            if any(x in raw for x in ["snack", "starter", "appetizer"]):\n                return "Snack"\n            if any(x in raw for x in ["dinner", "supper"]):\n                return "Dinner"\n            if "lunch" in raw:\n                return "Lunch"\n\n            # Name-based fallback.\n            if any(x in text for x in [\n                "dosa", "idli", "upma", "poha", "pongal",\n                "paratha", "pancake", "omelette", "omelet",\n                "puri", "vada", "uttapam", "toast"\n            ]):\n                return "Breakfast"\n\n            if any(x in text for x in [\n                "tea", "coffee", "pakora", "bajji", "bonda",\n                "samosa", "sandwich", "cutlet", "snack"\n            ]):\n                return "Snack"\n\n            return "Main"\n\n        # Score every recipe against the actual pantry.\n        scored = []\n\n        for _, row in df.iterrows():\n            ingredients = row["_mealora_ingredients"]\n            p = score_recipe(ingredients)\n\n            # Strongly discourage recipes that need many missing core items.\n            core = p["core_pantry"]\n\n            ml = max(\n                row_score(\n                    row,\n                    ["hgb_suitability_score", "rf_suitability_score",\n                     "ml_suitability_score"],\n                    0.5\n                ),\n                row_score(row, ["han_score"], 0.5)\n            )\n\n            context_score = row_score(\n                row,\n                ["context_score", "context_match_score"],\n                0.5\n            )\n\n            nutrition_score = row_score(\n                row,\n                ["nutrition_score", "nutrition_match_score"],\n                0.5\n            )\n\n            time_score = 1.0\n\n            if time_col:\n                try:\n                    t = float(row[time_col])\n                    if np.isfinite(t):\n                        time_score = float(\n                            np.clip(\n                                1.0 - max(t - max_time, 0) / max(max_time, 1),\n                                0,\n                                1\n                            )\n                        )\n                except Exception:\n                    pass\n\n            scored.append({\n                "recipe_id": str(row["_mealora_recipe_id"]),\n                "recipe_name": str(row["_mealora_recipe_name"]),\n                "ingredients": ingredients,\n                "pantry": p["pantry"],\n                "core_pantry": core,\n                "expiry": p["expiry"],\n                "matched_pantry": p["matched"],\n                "missing": p["missing"],\n                "missing_core": p["missing_core"],\n                "ml": ml,\n                "context": context_score,\n                "nutrition": nutrition_score,\n                "time": time_score,\n                "meal_role": classify_meal(\n                    row,\n                    str(row["_mealora_recipe_name"]),\n                    ingredients\n                ),\n                "cuisine": str(row[cuisine_col]) if cuisine_col else "",\n                "diet": str(row[diet_col]) if diet_col else "",\n                "cook_time": (\n                    float(row[time_col])\n                    if time_col\n                    and str(row[time_col]).strip()\n                    and str(row[time_col]).lower() != "nan"\n                    else None\n                ),\n            })\n\n        recipes = pd.DataFrame(scored)\n\n        # ------------------------------------------------------------\n        # User filters.\n        # ------------------------------------------------------------\n        def matches_filter(row):\n            if diet and diet.lower() not in ("mixed", "any", "auto", "automatic", "none"):\n                raw = str(row["diet"]).lower()\n                if raw and diet.lower() not in raw:\n                    return False\n\n            if cuisine and cuisine.lower() not in ("auto", "automatic", "any", "mixed", "none"):\n                raw = str(row["cuisine"]).lower()\n                if raw and cuisine.lower() not in raw:\n                    return False\n\n            return True\n\n        recipes = recipes[recipes.apply(matches_filter, axis=1)].copy()\n\n        # Pantry-first candidate gate.\n        # Main meals should normally use at least ~55% of their\n        # non-staple ingredients from the current pantry.\n        pantry_candidates = recipes[\n            recipes["core_pantry"] >= 0.55\n        ].copy()\n\n        # If the dataset/filter combination is restrictive, relax gradually.\n        if len(pantry_candidates) < 100:\n            pantry_candidates = recipes[\n                recipes["core_pantry"] >= 0.40\n            ].copy()\n\n        if len(pantry_candidates) < 50:\n            pantry_candidates = recipes[\n                recipes["pantry"] >= 0.35\n            ].copy()\n\n        if len(pantry_candidates) == 0:\n            pantry_candidates = recipes.sort_values(\n                ["core_pantry", "pantry", "ml"],\n                ascending=False\n            ).head(100).copy()\n\n        # Ranking deliberately gives pantry more influence than generic ML.\n        pantry_candidates["_base_score"] = (\n            0.42 * pantry_candidates["core_pantry"] +\n            0.16 * pantry_candidates["pantry"] +\n            0.12 * pantry_candidates["expiry"] +\n            0.10 * pantry_candidates["ml"] +\n            0.08 * pantry_candidates["context"] +\n            0.07 * pantry_candidates["nutrition"] +\n            0.05 * pantry_candidates["time"]\n        )\n\n        # ------------------------------------------------------------\n        # Meal-role pools.\n        # ------------------------------------------------------------\n        def is_breakfast(row):\n            return row["meal_role"] == "Breakfast"\n\n        def is_snack(row):\n            return row["meal_role"] == "Snack"\n\n        def is_main(row):\n            return row["meal_role"] in ("Lunch", "Dinner", "Main")\n\n        breakfast_pool = pantry_candidates[\n            pantry_candidates.apply(is_breakfast, axis=1)\n        ].copy()\n\n        main_pool = pantry_candidates[\n            pantry_candidates.apply(is_main, axis=1)\n        ].copy()\n\n        snack_pool = pantry_candidates[\n            pantry_candidates.apply(is_snack, axis=1)\n        ].copy()\n\n        if breakfast_pool.empty:\n            breakfast_pool = pantry_candidates.copy()\n\n        if main_pool.empty:\n            main_pool = pantry_candidates.copy()\n\n        if snack_pool.empty:\n            snack_pool = breakfast_pool.copy()\n\n        # Side dishes: prefer vegetable/dal/poriyal/kootu/raita/salad\n        # rather than letting any main recipe become a "side".\n        SIDE_TERMS = (\n            "poriyal", "sabzi", "subzi", "kootu", "thoran",\n            "dal", "sambar", "rasam", "raita", "salad",\n            "chutney", "kurma", "vegetable", "stir fry",\n            "palya", "avial", "bhaji"\n        )\n\n        side_pool = main_pool[\n            main_pool["recipe_name"].str.lower().apply(\n                lambda x: any(t in x for t in SIDE_TERMS)\n            )\n        ].copy()\n\n        if side_pool.empty:\n            side_pool = main_pool.copy()\n\n        # Weekend special recipes: biryani/pulao/etc., but ONLY if pantry-compatible.\n        TREAT_TERMS = (\n            "biryani", "biriyani", "pulao", "fried rice",\n            "korma", "tikka", "butter masala", "special"\n        )\n\n        special_pool = main_pool[\n            main_pool["recipe_name"].str.lower().apply(\n                lambda x: any(t in x for t in TREAT_TERMS)\n            )\n        ].copy()\n\n        if special_pool.empty:\n            special_pool = main_pool.copy()\n\n        # ------------------------------------------------------------\n        # Build 35 slots. NSGA-II optimizes the selected candidate\n        # combination, but candidates are already pantry-grounded.\n        # ------------------------------------------------------------\n        days = [\n            "Monday", "Tuesday", "Wednesday",\n            "Thursday", "Friday", "Saturday", "Sunday"\n        ]\n\n        slots = []\n        domains = []\n\n        def top_domain(pool, n=30):\n            if pool.empty:\n                return []\n            return list(\n                pool.sort_values(\n                    ["_base_score", "core_pantry", "expiry"],\n                    ascending=False\n                ).head(n).index\n            )\n\n        for day in days:\n            # Breakfast\n            slots.append((day, "breakfast"))\n            domains.append(top_domain(breakfast_pool, 35))\n\n            # Lunch main\n            slots.append((day, "lunch_main"))\n            domains.append(top_domain(main_pool, 45))\n\n            # Lunch side\n            slots.append((day, "lunch_side"))\n            domains.append(top_domain(side_pool, 35))\n\n            # Dinner main — special/treat on selected weekend day.\n            slots.append((day, "dinner_main"))\n            if day == special_day and special_day != "None":\n                domains.append(top_domain(special_pool, 45))\n            else:\n                domains.append(top_domain(main_pool, 45))\n\n            # Dinner side\n            slots.append((day, "dinner_side"))\n            domains.append(top_domain(side_pool, 35))\n\n        # Remove empty domains.\n        if any(not d for d in domains):\n            raise RuntimeError(\n                "Mealora could not build pantry-compatible candidate pools."\n            )\n\n        # Master candidate table. Keep recipe IDs as the stable key so\n        # breakfast/main/side pools can share the same candidate records.\n        candidates = pd.concat(\n            [\n                breakfast_pool,\n                main_pool,\n                side_pool,\n                special_pool\n            ],\n            ignore_index=True\n        ).drop_duplicates("recipe_id").reset_index(drop=True)\n\n        id_to_pos = {\n            str(row["recipe_id"]): i\n            for i, (_, row) in enumerate(candidates.iterrows())\n        }\n\n        # Rebuild every slot domain by recipe_id. This avoids dataframe-index\n        # collisions between the source pools.\n        domain_ids = []\n\n        for day, slot_name in slots:\n            if slot_name == "breakfast":\n                source_pool = breakfast_pool\n            elif slot_name in ("lunch_side", "dinner_side"):\n                source_pool = side_pool\n            elif (\n                slot_name == "dinner_main"\n                and day == special_day\n                and special_day != "None"\n            ):\n                source_pool = special_pool\n            else:\n                source_pool = main_pool\n\n            source_pool = source_pool.sort_values(\n                ["_base_score", "core_pantry", "expiry"],\n                ascending=False\n            ).head(45)\n\n            ids = [\n                id_to_pos[str(recipe_id)]\n                for recipe_id in source_pool["recipe_id"].tolist()\n                if str(recipe_id) in id_to_pos\n            ]\n\n            domain_ids.append(list(dict.fromkeys(ids)))\n\n        domains = domain_ids\n\n        # ------------------------------------------------------------\n        # NSGA-II objective.\n        # ------------------------------------------------------------\n        def fitness(chromosome):\n            rows = [candidates.iloc[i].to_dict() for i in chromosome]\n\n            pantry_score = np.mean([r["core_pantry"] for r in rows])\n            expiry_score = np.mean([r["expiry"] for r in rows])\n            ml_score = np.mean([r["ml"] for r in rows])\n            nutrition_score = np.mean([r["nutrition"] for r in rows])\n            context_score = np.mean([r["context"] for r in rows])\n            time_score = np.mean([r["time"] for r in rows])\n\n            recipe_names = [\n                str(r["recipe_name"]).strip().lower()\n                for r in rows\n            ]\n            unique = len(set(recipe_names)) / max(len(recipe_names), 1)\n\n            ingredient_sets = [\n                set(token_set(" ".join(r["ingredients"])))\n                for r in rows\n            ]\n\n            # Ingredient reuse is useful, but not so strong that every day\n            # becomes the same meal.\n            reuse_pairs = []\n            for i in range(1, len(ingredient_sets)):\n                if ingredient_sets[i] and ingredient_sets[i - 1]:\n                    reuse_pairs.append(\n                        len(\n                            ingredient_sets[i] &\n                            ingredient_sets[i - 1]\n                        ) /\n                        max(\n                            len(\n                                ingredient_sets[i] |\n                                ingredient_sets[i - 1]\n                            ),\n                            1\n                        )\n                    )\n\n            reuse = np.mean(reuse_pairs) if reuse_pairs else 0.5\n\n            purchase = np.mean([\n                1.0 - min(\n                    len(r["missing_core"]) /\n                    max(len(r["ingredients"]), 1),\n                    1.0\n                )\n                for r in rows\n            ])\n\n            # Pantry is intentionally first and strongest.\n            return np.array([\n                pantry_score,\n                expiry_score,\n                ml_score,\n                nutrition_score,\n                context_score,\n                time_score,\n                purchase,\n                reuse,\n                unique\n            ], dtype=float)\n\n        def dominates(a, b):\n            return np.all(a >= b) and np.any(a > b)\n\n        def fast_fronts(values):\n            n = len(values)\n            domination_count = [0] * n\n            dominated = [[] for _ in range(n)]\n            fronts = [[]]\n\n            for p in range(n):\n                for q in range(n):\n                    if p == q:\n                        continue\n                    if dominates(values[p], values[q]):\n                        dominated[p].append(q)\n                    elif dominates(values[q], values[p]):\n                        domination_count[p] += 1\n\n                if domination_count[p] == 0:\n                    fronts[0].append(p)\n\n            i = 0\n            while i < len(fronts) and fronts[i]:\n                next_front = []\n                for p in fronts[i]:\n                    for q in dominated[p]:\n                        domination_count[q] -= 1\n                        if domination_count[q] == 0:\n                            next_front.append(q)\n                if next_front:\n                    fronts.append(next_front)\n                i += 1\n\n            return fronts\n\n        def crowding(front, values):\n            distance = {i: 0.0 for i in front}\n\n            if len(front) <= 2:\n                for i in front:\n                    distance[i] = float("inf")\n                return distance\n\n            for obj in range(values.shape[1]):\n                ordered = sorted(\n                    front,\n                    key=lambda i: values[i, obj]\n                )\n\n                distance[ordered[0]] = float("inf")\n                distance[ordered[-1]] = float("inf")\n\n                low = values[ordered[0], obj]\n                high = values[ordered[-1], obj]\n\n                if high == low:\n                    continue\n\n                for k in range(1, len(ordered) - 1):\n                    distance[ordered[k]] += (\n                        values[ordered[k + 1], obj] -\n                        values[ordered[k - 1], obj]\n                    ) / (high - low)\n\n            return distance\n\n        def mutate(chromosome):\n            out = chromosome[:]\n            for i in range(len(out)):\n                if random.random() < 0.15:\n                    out[i] = random.choice(domains[i])\n            return out\n\n        random.seed(42)\n        np.random.seed(42)\n\n        pop_size = 50\n        generations = 30\n\n        population = [\n            [random.choice(domain) for domain in domains]\n            for _ in range(pop_size)\n        ]\n\n        best_front = None\n        best_values = None\n\n        for _ in range(generations):\n            values = np.array([\n                fitness(chromosome)\n                for chromosome in population\n            ])\n\n            fronts = fast_fronts(values)\n\n            if fronts and fronts[0]:\n                best_front = [\n                    population[i][:]\n                    for i in fronts[0]\n                ]\n                best_values = values[fronts[0]]\n\n            ranks = np.zeros(len(population), dtype=int)\n            crowd = np.zeros(len(population), dtype=float)\n\n            for rank, front in enumerate(fronts):\n                for i in front:\n                    ranks[i] = rank\n\n                cd = crowding(front, values)\n                for i, score in cd.items():\n                    crowd[i] = score\n\n            offspring = []\n\n            while len(offspring) < pop_size:\n                def pick():\n                    a = random.randrange(pop_size)\n                    b = random.randrange(pop_size)\n\n                    if (\n                        ranks[a] < ranks[b] or\n                        (\n                            ranks[a] == ranks[b] and\n                            crowd[a] > crowd[b]\n                        )\n                    ):\n                        return population[a][:]\n\n                    return population[b][:]\n\n                parent_a = pick()\n                parent_b = pick()\n\n                cut = random.randint(1, len(parent_a) - 1)\n\n                child_a = mutate(\n                    parent_a[:cut] + parent_b[cut:]\n                )\n                child_b = mutate(\n                    parent_b[:cut] + parent_a[cut:]\n                )\n\n                offspring.extend([child_a, child_b])\n\n            combined = population + offspring[:pop_size]\n\n            combined_values = np.array([\n                fitness(chromosome)\n                for chromosome in combined\n            ])\n\n            fronts = fast_fronts(combined_values)\n\n            new_population = []\n\n            for front in fronts:\n                if len(new_population) + len(front) <= pop_size:\n                    new_population.extend(\n                        combined[i] for i in front\n                    )\n                else:\n                    cd = crowding(front, combined_values)\n                    ordered = sorted(\n                        front,\n                        key=lambda i: cd[i],\n                        reverse=True\n                    )\n                    new_population.extend(\n                        combined[i]\n                        for i in ordered[\n                            :pop_size - len(new_population)\n                        ]\n                    )\n                    break\n\n            population = new_population\n\n        if not best_front:\n            raise RuntimeError(\n                "NSGA-II did not produce a weekly plan."\n            )\n\n        # Pantry-first final selection.\n        weights = np.array([\n            0.30,  # pantry\n            0.15,  # expiry\n            0.13,  # ML suitability\n            0.10,  # nutrition\n            0.08,  # context\n            0.07,  # time\n            0.07,  # purchase\n            0.05,  # ingredient reuse\n            0.05   # uniqueness\n        ])\n\n        selected = best_front[\n            int(\n                np.argmax([\n                    np.dot(\n                        np.clip(v, 0, 1),\n                        weights\n                    )\n                    for v in best_values\n                ])\n            )\n        ]\n\n        def serialize(index, is_treat=False):\n            row = candidates.iloc[int(index)]\n\n            return {\n                "recipe_id": str(row["recipe_id"]),\n                "recipe_name": str(row["recipe_name"]),\n                "suitability_score": round(\n                    float(row["ml"]), 4\n                ),\n                "pantry_score": round(\n                    float(row["core_pantry"]), 4\n                ),\n                "expiry_score": round(\n                    float(row["expiry"]), 4\n                ),\n                "context_score": round(\n                    float(row["context"]), 4\n                ),\n                "nutrition_score": round(\n                    float(row["nutrition"]), 4\n                ),\n                "purchase_score": round(\n                    1.0 - min(\n                        len(row["missing_core"]) /\n                        max(len(row["ingredients"]), 1),\n                        1.0\n                    ),\n                    4\n                ),\n                "matched_pantry": list(\n                    row["matched_pantry"]\n                )[:15],\n                "missing_ingredients": list(\n                    row["missing"]\n                )[:10],\n                "ingredients": list(\n                    row["ingredients"]\n                ),\n                "is_treat": bool(is_treat)\n            }\n\n        plan = []\n\n        # Selected chromosome has 35 positions:\n        # day * [breakfast, lunch main, lunch side, dinner main, dinner side]\n        for day_index, day in enumerate(days):\n            base = day_index * 5\n            special = (\n                special_day != "None"\n                and day == special_day\n            )\n\n            breakfast_i = selected[base]\n            lunch_i = selected[base + 1]\n            lunch_side_i = selected[base + 2]\n            dinner_i = selected[base + 3]\n            dinner_side_i = selected[base + 4]\n\n            # Prevent the same recipe from being its own side.\n            if (\n                candidates.iloc[lunch_side_i]["recipe_id"] ==\n                candidates.iloc[lunch_i]["recipe_id"]\n            ):\n                alternatives = domain_ids[base + 2]\n                alternatives = [\n                    x for x in alternatives\n                    if candidates.iloc[x]["recipe_id"] !=\n                    candidates.iloc[lunch_i]["recipe_id"]\n                ]\n                if alternatives:\n                    lunch_side_i = max(\n                        alternatives,\n                        key=lambda x:\n                        candidates.iloc[x]["core_pantry"]\n                    )\n\n            if (\n                candidates.iloc[dinner_side_i]["recipe_id"] ==\n                candidates.iloc[dinner_i]["recipe_id"]\n            ):\n                alternatives = domain_ids[base + 4]\n                alternatives = [\n                    x for x in alternatives\n                    if candidates.iloc[x]["recipe_id"] !=\n                    candidates.iloc[dinner_i]["recipe_id"]\n                ]\n                if alternatives:\n                    dinner_side_i = max(\n                        alternatives,\n                        key=lambda x:\n                        candidates.iloc[x]["core_pantry"]\n                    )\n\n            plan.append({\n                "day": day,\n                "theme": (\n                    "Weekend special / treat meal"\n                    if special\n                    else "Pantry-first balanced day"\n                ),\n                "is_special_day": special,\n                "breakfast": serialize(\n                    breakfast_i\n                ),\n                "lunch_main": serialize(\n                    lunch_i\n                ),\n                "lunch_side": serialize(\n                    lunch_side_i\n                ),\n                "dinner_main": serialize(\n                    dinner_i,\n                    special\n                ),\n                "dinner_side": serialize(\n                    dinner_side_i,\n                    special\n                )\n            })\n\n        # Snacks are selected separately from a pantry-grounded snack pool.\n        if include_snacks and not snack_pool.empty:\n            snack_pool = snack_pool.copy()\n\n            snack_pool["_snack_score"] = (\n                0.45 * snack_pool["core_pantry"] +\n                0.20 * snack_pool["pantry"] +\n                0.15 * snack_pool["expiry"] +\n                0.10 * snack_pool["nutrition"] +\n                0.10 * snack_pool["ml"]\n            )\n\n            snack_pool = snack_pool.sort_values(\n                "_snack_score",\n                ascending=False\n            ).drop_duplicates(\n                "recipe_id"\n            ).reset_index(drop=True)\n\n            for i, day_plan in enumerate(plan):\n                row = snack_pool.iloc[\n                    i % len(snack_pool)\n                ]\n\n                # Find corresponding candidate row.\n                candidate_matches = candidates.index[\n                    candidates["recipe_id"].astype(str) ==\n                    str(row["recipe_id"])\n                ].tolist()\n\n                if candidate_matches:\n                    day_plan["snack"] = serialize(\n                        candidate_matches[0]\n                    )\n                else:\n                    day_plan["snack"] = {\n                        "recipe_id": str(row["recipe_id"]),\n                        "recipe_name": str(row["recipe_name"]),\n                        "suitability_score": round(float(row["ml"]), 4),\n                        "pantry_score": round(float(row["core_pantry"]), 4),\n                        "expiry_score": round(float(row["expiry"]), 4),\n                        "context_score": round(float(row["context"]), 4),\n                        "nutrition_score": round(float(row["nutrition"]), 4),\n                        "purchase_score": round(\n                            1.0 - min(\n                                len(row["missing_core"]) /\n                                max(len(row["ingredients"]), 1),\n                                1.0\n                            ),\n                            4\n                        ),\n                        "matched_pantry": list(\n                            row["matched_pantry"]\n                        )[:15],\n                        "missing_ingredients": list(\n                            row["missing"]\n                        )[:10],\n                        "ingredients": list(row["ingredients"]),\n                        "is_treat": False\n                    }\n\n        all_meals = []\n\n        for day in plan:\n            for key in (\n                "breakfast",\n                "lunch_main",\n                "lunch_side",\n                "dinner_main",\n                "dinner_side",\n                "snack"\n            ):\n                if day.get(key):\n                    all_meals.append(day[key])\n\n        def average(key, default=0.5):\n            if not all_meals:\n                return default\n            return float(\n                np.mean([\n                    float(x.get(key, default))\n                    for x in all_meals\n                ])\n            )\n\n        unique_recipes = len({\n            x["recipe_id"]\n            for x in all_meals\n        })\n\n        # A weekly planner should never claim "0% pantry" when\n        # candidates were pantry-grounded.\n        pantry_utilization = average("pantry_score", 0)\n        expiry_utilization = average("expiry_score", 0)\n\n        return jsonify({\n            "success": True,\n            "context": ctx,\n            "plan": plan,\n            "summary": {\n                "meals_planned": len(all_meals),\n                "unique_recipes": unique_recipes,\n                "pantry_utilization": round(\n                    pantry_utilization * 100, 1\n                ),\n                "expiry_utilization": round(\n                    expiry_utilization * 100, 1\n                ),\n                "nutrition_score": round(\n                    average("nutrition_score") * 100, 1\n                ),\n                "context_score": round(\n                    average("context_score") * 100, 1\n                ),\n                "purchase_burden": round(\n                    (1.0 - average("purchase_score")) * 100,\n                    1\n                ),\n                "algorithm": (\n                    "Pantry-first full-dataset candidate scoring "\n                    "+ RF/HAN signals + NSGA-II multi-objective optimization"\n                ),\n                "optimizer_generations": generations,\n                "optimizer_population": pop_size,\n                "planning_horizon": "7 days",\n                "candidate_recipes_evaluated": int(len(recipes)),\n                "pantry_grounded_candidates": int(len(pantry_candidates)),\n                "pantry_items_received": int(len(pantry_names)),\n                "objectives": [\n                    "pantry coverage",\n                    "expiry utilization",\n                    "learned suitability",\n                    "nutrition",\n                    "context",\n                    "time fit",\n                    "purchase burden",\n                    "ingredient reuse",\n                    "recipe variety"\n                ]\n            }\n        })\n\n    except Exception as e:\n        import traceback\n        traceback.print_exc()\n        return jsonify({\n            "success": False,\n            "error": str(e)\n        }), 500\n\n\n# ===== MEALORA WEEKLY PLANNER V3 END =====\n'

source = BACKEND.read_text(encoding="utf-8")
